import { Box, Typography, Card, CardContent, Chip } from '@mui/material';
import { ShoppingBag, Package, BarChart3 } from 'lucide-react';

export default function BasketStats({ baskets, transactions }) {
  const totalItems = baskets.reduce((s, b) => s + b.products.length, 0);
  const avgItems = baskets.length ? (totalItems / baskets.length).toFixed(1) : 0;
  const avgValue = transactions?.avg_per_order ? (transactions.avg_per_order * 20).toFixed(0) : '—';

  return (
    <Card sx={{ height: '100%' }}>
      <CardContent sx={{ p: { xs: 2, md: 2.5 } }}>
        <Typography variant="h6" sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 2 }}>
          <ShoppingBag size={18} color="#f97316" />
          Analyse des Paniers Clients
        </Typography>
        <Box sx={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 1.5, mb: 2.5 }}>
          {[
            { label: 'Paniers Chargés', value: baskets.length, icon: ShoppingBag, color: '#f97316' },
            { label: 'Produits / Panier', value: avgItems, icon: Package, color: '#6366f1' },
            { label: 'Total Articles', value: totalItems, icon: BarChart3, color: '#10b981' },
            { label: 'Transactions Total', value: transactions?.total_transactions?.toLocaleString('fr-FR') || '—', icon: ShoppingBag, color: '#8b5cf6' },
          ].map((s) => (
            <Box key={s.label} sx={{ bgcolor: 'rgba(255,255,255,0.03)', borderRadius: 2, p: 1.5, textAlign: 'center' }}>
              <s.icon size={16} color={s.color} style={{ marginBottom: 4 }} />
              <Typography sx={{ fontSize: '1.1rem', fontWeight: 700, fontFamily: 'monospace', color: s.color }}>{s.value}</Typography>
              <Typography variant="body2" sx={{ fontSize: '0.65rem', mt: 0.2 }}>{s.label}</Typography>
            </Box>
          ))}
        </Box>
        <Typography variant="subtitle2" sx={{ mb: 1.5 }}>Derniers Paniers</Typography>
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
          {baskets.slice(0, 5).map((b) => (
            <Box key={b.order_id} sx={{ display: 'flex', alignItems: 'center', gap: 1, bgcolor: 'rgba(255,255,255,0.02)', borderRadius: 1.5, px: 1.5, py: 1 }}>
              <Typography sx={{ fontFamily: 'monospace', fontSize: '0.65rem', color: '#6b7280', minWidth: 70 }}>{b.order_id}</Typography>
              <Box sx={{ display: 'flex', gap: 0.3, flex: 1, flexWrap: 'wrap' }}>
                {b.products.slice(0, 4).map((pid) => (
                  <Chip key={pid} label={pid.length > 15 ? pid.slice(0, 15) + '…' : pid} size="small" sx={{ background: 'rgba(249,115,22,0.1)', color: '#f97316', fontSize: '0.55rem', height: 20 }} />
                ))}
                {b.products.length > 4 && <Typography sx={{ fontSize: '0.6rem', color: '#6b7280', alignSelf: 'center' }}>+{b.products.length - 4}</Typography>}
              </Box>
              <Box sx={{ textAlign: 'right' }}>
                <Typography sx={{ fontSize: '0.65rem', color: '#6b7280', fontFamily: 'monospace' }}>{b.products.length} art.</Typography>
                {b.total && <Typography sx={{ fontSize: '0.65rem', color: '#10b981', fontFamily: 'monospace' }}>{b.total.toFixed(2)} MAD</Typography>}
              </Box>
            </Box>
          ))}
        </Box>
      </CardContent>
    </Card>
  );
}
