import { Box, Typography, Stepper, Step, StepLabel } from '@mui/material';
import { Database, Cpu, BarChart3, MessageCircle, CheckCircle2, Circle } from 'lucide-react';

const STEPS = [
  { id: 'hdfs', label: 'HDFS & Data Prep', desc: 'Anas', icon: Database },
  { id: 'map', label: 'Phase Map', desc: 'Ilyas', icon: Cpu },
  { id: 'reduce', label: 'Phase Reduce + ML', desc: 'Ahmed', icon: BarChart3 },
  { id: 'dashboard', label: 'Dashboard', desc: 'Bilal', icon: MessageCircle },
];

function CustomStepIcon({ active, completed, icon }) {
  const StepIcon = STEPS[icon - 1]?.icon || Circle;
  return (
    <Box sx={{ width: 32, height: 32, borderRadius: 2, display: 'flex', alignItems: 'center', justifyContent: 'center', background: completed || active ? 'rgba(249,115,22,0.12)' : 'rgba(255,255,255,0.04)' }}>
      {completed ? <CheckCircle2 size={16} color="#f97316" /> : <StepIcon size={16} color={active ? '#f97316' : '#6b7280'} />}
    </Box>
  );
}

export default function PipelineStatus({ currentStep = 'dashboard' }) {
  const idx = Math.max(STEPS.findIndex((s) => s.id === currentStep), 0);

  return (
    <Box sx={{ bgcolor: 'background.paper', borderRadius: 2.5, border: '1px solid', borderColor: 'divider', p: 1.5, px: 2 }}>
      <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 1 }}>
        <Typography variant="h6" sx={{ fontSize: '0.82rem' }}>État du Pipeline Big Data</Typography>
        <Typography variant="body2" sx={{ fontSize: '0.6rem', color: '#6b7280' }}>Dernière màj: 30/05/2026 14:30</Typography>
      </Box>
      <Stepper activeStep={idx} alternativeLabel
        sx={{ '& .MuiStepLabel-label': { fontSize: '0.7rem', fontWeight: 600, mt: 0.5 }, '& .MuiStepConnector-line': { borderColor: 'rgba(255,255,255,0.06)' } }}>
        {STEPS.map((s) => (
          <Step key={s.id}>
            <StepLabel StepIconComponent={CustomStepIcon}>
              {s.label}
              <Typography variant="body2" sx={{ fontSize: '0.55rem', color: '#6b7280' }}>{s.desc}</Typography>
            </StepLabel>
          </Step>
        ))}
      </Stepper>
    </Box>
  );
}
